<?php
/** Bounded job, outbox, reconciliation and cleanup workers. */
defined( 'ABSPATH' ) || exit;
final class VWLB_Jobs {
	public static function process($limit=5){global $wpdb;$table=VWLB_Helpers::table('processing_jobs');$worker=VWLB_Helpers::public_id('worker');$jobs=$wpdb->get_results($wpdb->prepare("SELECT * FROM $table WHERE status IN ('pending','retry') AND available_at<=%s AND (locked_at IS NULL OR locked_at<%s) ORDER BY priority ASC,id ASC LIMIT %d",VWLB_Helpers::now(),gmdate('Y-m-d H:i:s',time()-15*MINUTE_IN_SECONDS),max(1,min(20,(int)$limit))),ARRAY_A);foreach($jobs as $job){$locked=$wpdb->update($table,array('status'=>'running','locked_at'=>VWLB_Helpers::now(),'locked_by'=>$worker,'attempts'=>(int)$job['attempts']+1,'updated_at'=>VWLB_Helpers::now()),array('id'=>$job['id'],'status'=>$job['status']),array('%s','%s','%s','%d','%s'),array('%d','%s'));if(!$locked)continue;self::run_job($job);}}
	private static function run_job($job){global $wpdb;$table=VWLB_Helpers::table('processing_jobs');$asset=$job['asset_id']?VWLB_Repository::find('media_assets',$job['asset_id']):array();$result=null;if('verify_and_process'===$job['job_type']){if(!$asset||!VWLB_Media::verify_magic($asset))$result=VWLB_Helpers::error('vwlb_asset_validation_failed',__('Media validation failed.',VWLB_TEXT_DOMAIN),422);else{$wpdb->update(VWLB_Helpers::table('media_assets'),array('status'=>'processing','scan_status'=>'passed','updated_at'=>VWLB_Helpers::now()),array('id'=>$asset['id']));$provider=VWLB_Providers::get($asset['provider']);$result=$provider?$provider->process_asset($asset,$job):VWLB_Helpers::error('vwlb_provider_missing',__('Media provider unavailable.',VWLB_TEXT_DOMAIN),503);}}elseif('finalize_live_recording'===$job['job_type']){$result=apply_filters('vwlb_finalize_live_recording',VWLB_Helpers::error('vwlb_recording_processor_unavailable',__('Recording finalizer is not configured.',VWLB_TEXT_DOMAIN),503),VWLB_Helpers::json($job['input_json']),$job);}else{$result=apply_filters('vwlb_process_job',VWLB_Helpers::error('vwlb_unknown_job',__('Unknown processing job.',VWLB_TEXT_DOMAIN),422),$job,$asset);}if(is_wp_error($result)){self::fail_or_retry($job,$result);return;}$wpdb->update($table,array('status'=>'complete','output_json'=>VWLB_Helpers::json_encode($result),'locked_at'=>null,'locked_by'=>null,'updated_at'=>VWLB_Helpers::now()),array('id'=>$job['id']));if($asset){$derivatives=$result['derivatives']??VWLB_Helpers::json($asset['derivatives_json']);$wpdb->update(VWLB_Helpers::table('media_assets'),array('status'=>$result['status']??'ready','scan_status'=>'passed','derivatives_json'=>VWLB_Helpers::json_encode($derivatives),'error_code'=>'','error_message'=>'','version'=>(int)$asset['version']+1,'updated_at'=>VWLB_Helpers::now()),array('id'=>$asset['id'],'version'=>$asset['version']));VWLB_Helpers::audit('asset',$asset['id'],'processing_complete',$asset['status'],$result['status']??'ready');VWLB_Helpers::outbox('MediaAssetReady','asset',$asset['id'],array('public_id'=>$asset['public_id']));}}
	private static function fail_or_retry($job,$error){global $wpdb;$attempt=(int)$job['attempts']+1;$retry=$attempt<(int)$job['max_attempts'];$wpdb->update(VWLB_Helpers::table('processing_jobs'),array('status'=>$retry?'retry':'dead','available_at'=>gmdate('Y-m-d H:i:s',time()+min(HOUR_IN_SECONDS,pow(2,$attempt)*60)),'locked_at'=>null,'locked_by'=>null,'error_code'=>$error->get_error_code(),'error_message'=>$error->get_error_message(),'updated_at'=>VWLB_Helpers::now()),array('id'=>$job['id']));if(!$retry&&$job['asset_id']){$asset=VWLB_Repository::find('media_assets',$job['asset_id']);if($asset)$wpdb->update(VWLB_Helpers::table('media_assets'),array('status'=>'failed','error_code'=>$error->get_error_code(),'error_message'=>$error->get_error_message(),'version'=>(int)$asset['version']+1,'updated_at'=>VWLB_Helpers::now()),array('id'=>$asset['id'],'version'=>$asset['version']));}VWLB_Helpers::audit('job',$job['id'],$retry?'retry':'dead',$job['status'],$retry?'retry':'dead',$error->get_error_message(),array('code'=>$error->get_error_code()));}
	public static function publish_outbox($limit=20){global $wpdb;$table=VWLB_Helpers::table('outbox');$events=$wpdb->get_results($wpdb->prepare("SELECT * FROM $table WHERE status IN ('pending','retry') AND available_at<=%s ORDER BY id ASC LIMIT %d",VWLB_Helpers::now(),max(1,min(100,(int)$limit))),ARRAY_A);foreach($events as $event){$wpdb->update($table,array('status'=>'publishing','attempts'=>(int)$event['attempts']+1,'locked_at'=>VWLB_Helpers::now(),'updated_at'=>VWLB_Helpers::now()),array('id'=>$event['id'],'status'=>$event['status']));try{do_action('vwlb_domain_event',$event['event_name'],VWLB_Helpers::json($event['payload_json']),$event);$wpdb->update($table,array('status'=>'published','published_at'=>VWLB_Helpers::now(),'last_error'=>'','updated_at'=>VWLB_Helpers::now()),array('id'=>$event['id']));}catch(Throwable $e){$attempt=(int)$event['attempts']+1;$wpdb->update($table,array('status'=>$attempt>=8?'dead':'retry','available_at'=>gmdate('Y-m-d H:i:s',time()+min(HOUR_IN_SECONDS,pow(2,$attempt)*30)),'last_error'=>mb_substr($e->getMessage(),0,1000),'updated_at'=>VWLB_Helpers::now()),array('id'=>$event['id']));}}}
	public static function reconcile(){global $wpdb;$now=VWLB_Helpers::now();$videos=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.VWLB_Helpers::table('videos').' WHERE status=%s AND scheduled_at<=%s LIMIT 100','scheduled',$now),ARRAY_A);foreach($videos as $v){$ok=VWLB_Videos::publication_gate($v);if(true===$ok){VWLB_Repository::update_versioned('videos',$v['id'],$v['version'],array('status'=>'published','published_at'=>$now));VWLB_Helpers::outbox('VideoPublished','video',$v['id'],array('scheduled'=>true));}}$events=$wpdb->get_results("SELECT * FROM ".VWLB_Helpers::table('live_events')." WHERE status IN ('scheduled','live','interrupted') LIMIT 100",ARRAY_A);foreach($events as $event){$provider=VWLB_Providers::get($event['provider']);if($provider){$state=$provider->reconcile('live',$event);if(is_array($state))$wpdb->update(VWLB_Helpers::table('live_events'),array('provider_state_json'=>VWLB_Helpers::json_encode(array_merge(VWLB_Helpers::json($event['provider_state_json']),$state)),'updated_at'=>$now),array('id'=>$event['id']));}}}
	public static function cleanup(){global $wpdb;$now=VWLB_Helpers::now();foreach(array('idempotency'=>'expires_at','rate_limits'=>'window_ends_at','playback_sessions'=>'expires_at','rollback_snapshots'=>'expires_at') as $table=>$column){$wpdb->query($wpdb->prepare('DELETE FROM '.VWLB_Helpers::table($table)." WHERE $column IS NOT NULL AND $column<%s LIMIT 1000",$now));}$wpdb->query($wpdb->prepare('UPDATE '.VWLB_Helpers::table('stream_credentials')." SET status='expired' WHERE status='active' AND expires_at IS NOT NULL AND expires_at<%s",$now));}
}
